WITH base AS (SELECT *, ROUND(cost * 0.85, 2) AS adjusted_cost FROM shipments WHERE shipped_date >= '2024-12-15'), shipments_stats AS (SELECT carrier, CASE WHEN adjusted_cost >= 84 THEN 'high' WHEN adjusted_cost >= 10 THEN 'mid' ELSE 'low' END AS adjusted_cost_bucket, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(status))) AS status_values FROM base GROUP BY carrier, CASE WHEN adjusted_cost >= 84 THEN 'high' WHEN adjusted_cost >= 10 THEN 'mid' ELSE 'low' END) SELECT carrier, adjusted_cost_bucket FROM shipments_stats ORDER BY adjusted_cost_bucket;
